-- =========================================================
-- 5. BOOKINGS
-- =========================================================
-- Demo date: 25 September 2026
--
-- Morning: employees 1-10
-- Evening: employees 11-14
-- Night: employees 19-22
--
-- Employees 15-18 and 23-25 remain unbooked.
-- They can be used for demonstrating late bookings.
-- =========================================================

INSERT INTO bookings
(
    employee_id,
    shift_id,
    booking_date,
    status
)
SELECT
    e.id,
    1,
    '2026-09-25',
    'ACTIVE'
FROM employees e
JOIN users u
    ON e.user_id = u.id
WHERE u.username IN
(
    'demo01',
    'demo02',
    'demo03',
    'demo04',
    'demo05',
    'demo06',
    'demo07',
    'demo08',
    'demo09',
    'demo10'
);


