-- =========================================================
-- 6. ONE CANCELLED BOOKING
-- =========================================================
-- This provides cancellation history without affecting
-- the main active pool.
-- =========================================================

INSERT INTO bookings
(
    employee_id,
    shift_id,
    booking_date,
    status
)
SELECT
    e.id,
    1,
    '2026-09-25',
    'CANCELLED'
FROM employees e
JOIN users u
    ON e.user_id = u.id
WHERE u.username = 'demo15';


